import{_ as a,o,c as t,ag as s}from"./chunks/framework.CAXxHpAX.js";const u=JSON.parse('{"title":"Protobuf 契约设计总览","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dev/proto/proto.md","filePath":"guide/dev/proto/proto.md","lastUpdated":null}'),n={name:"guide/dev/proto/proto.md"};function p(l,e,d,c,i,r){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="protobuf-契约设计总览" tabindex="-1">Protobuf 契约设计总览 <a class="header-anchor" href="#protobuf-契约设计总览" aria-label="Permalink to &quot;Protobuf 契约设计总览&quot;">​</a></h1><blockquote><p>Protobuf 是 Deepsight 的跨进程、跨语言、跨模块契约。Hello 阶段的目标不是把网络、存储、进程/调度的所有字段一次性设计完，而是先建立稳定总线和模块插槽，让后续模块开发只扩展 payload，不重写通信链路。</p></blockquote><hr><h2 id="一、目录分层" tabindex="-1">一、目录分层 <a class="header-anchor" href="#一、目录分层" aria-label="Permalink to &quot;一、目录分层&quot;">​</a></h2><p>当前 proto 分为三层：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proto/</span></span>
<span class="line"><span>  common/</span></span>
<span class="line"><span>    common.proto          # 全局枚举和基础类型</span></span>
<span class="line"><span>  modules/</span></span>
<span class="line"><span>    network.proto         # 网络模块 payload</span></span>
<span class="line"><span>    storage.proto         # 存储模块 payload</span></span>
<span class="line"><span>    process.proto         # 进程/调度模块 payload</span></span>
<span class="line"><span>  v1/</span></span>
<span class="line"><span>    telemetry.proto       # DeepsightGateway 总线协议</span></span></code></pre></div><p>生成后的 Go API 位于：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api/</span></span>
<span class="line"><span>  common/</span></span>
<span class="line"><span>  modules/</span></span>
<span class="line"><span>  v1/</span></span></code></pre></div><h3 id="common" tabindex="-1"><code>common</code> <a class="header-anchor" href="#common" aria-label="Permalink to &quot;\`common\`&quot;">​</a></h3><p><code>common</code> 放跨模块共享的基础语义，例如：</p><ul><li><code>Severity</code>：事件严重级别</li><li><code>Status</code>：任务状态</li><li><code>Action</code>：控制面动作</li></ul><p>这些类型不能被某个模块私有化。网络丢包、慢 I/O、进程异常都应该复用同一套严重级别和任务状态。</p><h3 id="modules" tabindex="-1"><code>modules</code> <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;\`modules\`&quot;">​</a></h3><p><code>modules</code> 放业务模块自己的 payload。</p><p>Hello 阶段只定义最小壳：</p><ul><li><code>NetworkMetric</code> / <code>NetworkEvent</code> / <code>TraceNetworkArgs</code></li><li><code>StorageMetric</code> / <code>StorageEvent</code> / <code>TraceStorageArgs</code></li><li><code>ProcessMetric</code> / <code>ProcessEvent</code> / <code>TraceProcessArgs</code></li></ul><p>这些结构会随着模块开发逐步增加字段。它们不应该包含传输控制字段，例如 <code>session_token</code>、<code>time_offset_ns</code>、<code>truncated_count</code>；这些属于总线 wrapper。</p><h3 id="v1" tabindex="-1"><code>v1</code> <a class="header-anchor" href="#v1" aria-label="Permalink to &quot;\`v1\`&quot;">​</a></h3><p><code>v1/telemetry.proto</code> 是稳定通信总线，定义：</p><ul><li><code>Register</code></li><li><code>PushTelemetry</code></li><li><code>TaskChannel</code></li><li><code>TelemetryBatch</code></li><li><code>MetricWrapper</code></li><li><code>EventWrapper</code></li><li><code>TaskRequest</code> / <code>TaskResponse</code></li></ul><p>后续新增模块时，优先扩展 <code>proto/modules/*.proto</code>，只有需要把新模块接入总线时，才修改 <code>v1/telemetry.proto</code> 的 <code>oneof payload</code>。</p><hr><h2 id="二、核心模型" tabindex="-1">二、核心模型 <a class="header-anchor" href="#二、核心模型" aria-label="Permalink to &quot;二、核心模型&quot;">​</a></h2><p>Deepsight 的数据模型是二维的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数据类型维度：Metric / Event</span></span>
<span class="line"><span>业务模块维度：Network / Storage / Process</span></span></code></pre></div><p>这两个维度是正交的。</p><p>例如：</p><table tabindex="0"><thead><tr><th>数据</th><th>类型</th><th>模块</th></tr></thead><tbody><tr><td>TCP 当前连接数</td><td>Metric</td><td>Network</td></tr><tr><td>某次内核丢包栈</td><td>Event</td><td>Network</td></tr><tr><td>平均 I/O 延迟</td><td>Metric</td><td>Storage</td></tr><tr><td>某次慢 I/O 事件</td><td>Event</td><td>Storage</td></tr><tr><td>进程执行 <code>execve</code></td><td>Event</td><td>Process</td></tr><tr><td>上下文切换次数/秒</td><td>Metric</td><td>Process</td></tr></tbody></table><p>因此总线里不是简单定义 <code>NetworkMessage</code> 或 <code>StorageMessage</code>，而是先分成 <code>metrics</code> 和 <code>spontaneous_events</code>，再通过 <code>oneof payload</code> 指定模块。</p><hr><h2 id="三、metric-与-event" tabindex="-1">三、Metric 与 Event <a class="header-anchor" href="#三、metric-与-event" aria-label="Permalink to &quot;三、Metric 与 Event&quot;">​</a></h2><h3 id="metric" tabindex="-1">Metric <a class="header-anchor" href="#metric" aria-label="Permalink to &quot;Metric&quot;">​</a></h3><p>Metric 是高频、连续、可聚合的状态信号。</p><p>典型特征：</p><ul><li>频率高</li><li>上下文少</li><li>单条价值低</li><li>适合时间窗口聚合</li><li>通常不需要持久化</li></ul><p>处理路径：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Probe eBPF Map / 采样器</span></span>
<span class="line"><span>  -&gt; Transformer</span></span>
<span class="line"><span>  -&gt; MetricWrapper</span></span>
<span class="line"><span>  -&gt; TelemetryBatch.metrics</span></span>
<span class="line"><span>  -&gt; Server memory sliding window</span></span>
<span class="line"><span>  -&gt; MCP Resource</span></span></code></pre></div><h3 id="event" tabindex="-1">Event <a class="header-anchor" href="#event" aria-label="Permalink to &quot;Event&quot;">​</a></h3><p>Event 是低频、突发、有上下文的诊断证据。</p><p>典型特征：</p><ul><li>代表具体发生的行为或异常</li><li>包含 pid、comm、原因、栈、目标对象等上下文</li><li>适合大模型单独解释</li><li>可能需要防抖、去重、持久化</li></ul><p>处理路径：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Probe eBPF RingBuffer / 阈值触发</span></span>
<span class="line"><span>  -&gt; Transformer</span></span>
<span class="line"><span>  -&gt; EventWrapper</span></span>
<span class="line"><span>  -&gt; TelemetryBatch.spontaneous_events</span></span>
<span class="line"><span>  -&gt; Server event queue / debounce / persistence</span></span>
<span class="line"><span>  -&gt; MCP Tool result</span></span></code></pre></div><p>Hello 阶段当前真实事件 <code>execve</code> 被归类为 <code>ProcessEvent</code>，进入 <code>spontaneous_events</code>。</p><hr><h2 id="四、模块接入流程" tabindex="-1">四、模块接入流程 <a class="header-anchor" href="#四、模块接入流程" aria-label="Permalink to &quot;四、模块接入流程&quot;">​</a></h2><p>新增或扩展模块时遵守固定流程：</p><ol><li>在 <code>proto/modules/&lt;module&gt;.proto</code> 定义或扩展模块 payload。</li><li>如果是新模块，在 <code>proto/v1/telemetry.proto</code> 的 <code>MetricWrapper</code> / <code>EventWrapper</code> / <code>TaskRequest</code> oneof 中注册。</li><li>执行 <code>make proto</code> 生成 <code>api/</code>。</li><li>Probe transformer 将内部 raw 数据转换为对应 payload。</li><li>Server dispatcher 增加对应 oneof 分支。</li><li>增加单元测试，保证模块 payload 能被构造、发送、分发。</li></ol><p>对于已有模块，只新增字段时通常不需要修改总线；只要扩展 <code>proto/modules/*.proto</code> 并重新生成 API。</p><hr><h2 id="五、文档索引" tabindex="-1">五、文档索引 <a class="header-anchor" href="#五、文档索引" aria-label="Permalink to &quot;五、文档索引&quot;">​</a></h2><ul><li><a href="/guide/dev/proto/telemetry-bus">Telemetry 总线设计</a></li><li><a href="/guide/dev/proto/module-payloads">模块 Payload 设计与扩展规范</a></li><li><a href="/guide/dev/proto/compatibility">兼容性规则</a></li></ul>`,52)])])}const m=a(n,[["render",p]]);export{u as __pageData,m as default};
